import json, random, sys, io, subprocess, os
sys.path.insert(0, '/app/work')
import gen, ref

def norm_class(c):
    lits = sorted((l['atom'], l['negated']) for l in c['representative']['or'])
    return (c['signature'], c['members'], lits)

def run_main(req):
    p = subprocess.run([sys.executable, '/app/submission/main.py'],
                       input=json.dumps(req).encode(), capture_output=True)
    if p.returncode != 0:
        return ('CRASH', p.stderr.decode()[-2000:])
    return json.loads(p.stdout.decode())

rnd = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 200
bad = 0
for it in range(N):
    req = gen.gen_request(rnd)
    try:
        classes, qout = ref.ref_process(req)
    except Exception as e:
        print('REF CRASH', it, e); bad += 1; continue
    got = run_main(req)
    if isinstance(got, tuple):
        print('MAIN CRASH', it, got); bad += 1; continue
    if 'error' in got:
        print('MAIN ERROR', it, got); print(json.dumps(req)); bad += 1; continue
    gcls = sorted(norm_class(c) for c in got['classes'])
    rcls = sorted(norm_class(c) for c in classes)
    if gcls != rcls:
        print('CLASS MISMATCH', it); print(json.dumps(req)); print('got', gcls); print('ref', rcls); bad += 1; continue
    gq = got['queries']
    if len(gq) != len(qout):
        print('QLEN MISMATCH', it, len(gq), len(qout)); bad += 1; continue
    for i, (g, r) in enumerate(zip(gq, qout)):
        if (g['must'], g['may'], g['status']) != (r['must'], r['may'], r['status']):
            print('QUERY MISMATCH', it, i, g, r); print(json.dumps(req)); bad += 1; break
print('done, bad =', bad, 'of', N)
PYEOF
